import { useState } from 'react';
import { trace, useSnapshot } from '@observatory/lab';

export default function App() {
  const [count, setCount] = useState(0);
  trace.render('Counter', { count });
  useSnapshot('Counter', { count });
  function increment() {
    trace.action('Три обновления', { before: count });
    setCount((n) => n + 1);
    setCount((n) => n + 1);
    setCount((n) => n + 1);
  }
  return (
    <section>
      <span className="eyebrow">Счётчик</span>
      <h1>{count}</h1>
      <p>Три вызова setCount. Какой будет результат?</p>
      <button onClick={increment}>Увеличить трижды</button>
    </section>
  );
}
